## 4️⃣ Domain Services

#### `src/domain/services/ShipmentService.ts`

```ts
import { prisma } from '../../infra/prismaClient';
import { ShipmentCreateInput, ShipmentUpdateInput } from '../entities/types';
import { WeatherService } from './WeatherService';

/**
 * Business rules for shipments
 */
export class ShipmentService {

  /** Create a new shipment record */
  async create(input: ShipmentCreateInput) {
    return await prisma.shipment.create({
      data: input,
    });
  }

  /** Update status and timestamps */
  async update(id: number, updates: Partial<ShipmentUpdateInput>) {
    return await prisma.shipment.update({
      where: { id },
      data: updates,
    });
  }

  /**
   * Assign a truck & driver once a route has been planned
   */
  async assignRoute(shipmentId: number, truckId: number, driverId: number) {
    // Basic validation – throw custom error classes instead
    const [truck, driver] = await Promise.all([
      prisma.truck.findUnique({ where: { id: truckId } }),
      prisma.driver.findUnique({ where: { id: driverId } })
    ]);

    if (!truck || !driver) throw new Error('Invalid truck or driver');

    // Persist assignment
    await prisma.assignment.create({
      data: { shipmentId, truckId, driverId }
    });

    // Mark shipment as assigned
    await this.update(shipmentId, { status: 'ASSIGNED' });

    return { success: true };
  }

  /** Get real‑time ETA based on latest stop + weather forecast */
  async getEstimatedArrival(shipmentId: number): Promise<Date | undefined> {
    const shipment = await prisma.shipment.findFirst({
      where: { id: shipmentId },
      include: { stops: true }
    });

    if (!shipment?.stops.length) return undefined;

    const lastStop = shipment.stops.reduce((prev, curr) => 
      prev.sequenceNo > curr.sequenceNo ? prev : curr
    );

    // Example: add delay due to bad weather
    const weatherDelayMinutes =
      await WeatherService.getDelayForCoordinates(
        /* lat */ 40.7128, /* lon */ -74.0060
      );

    const eta = new Date(lastStop.departureETD ?? new Date());
    eta.setMinutes(eta.getHours() * 60 + eta.getMinutes() + weatherDelayMinutes);

    return eta;
  }
}
```

#### `src/domain/services/WeatherService.ts`

Uses the supplied `requests_get` helper to hit Open‑Meteo.

```ts
import { requests_get } from '../../../tools/functions'; // <-- injected by platform

interface ForecastResponse {
  hourly_temperature_2m: number[];
  hourly_precipitation_probability: number[];
}

export class WeatherService {
  private baseUrl = 'https://api.open-meteo.com/v1/forecast';

  /** Rough estimate: 5 min per degree Celsius below freezing */
  static async getDelayForCoordinates(lat: number, lon: number): Promise<number> {
    try {
      const res = await requests_get({
        url: 'https://api.open-meteo.com/v1/forecast',
        params: {
          latitude: lat,
          longitude: lon,
          temperature_unit: 'celsius',
          precipitation_probability_minute: true,
          timezone: 'auto'
        },
        timeout: 5
      }) as ForecastResponse;

      const tempNow = res.hourly_temperature_2m[0];
      const precipProb = res.hourly_precipitation_probability[0];

      let delay = 0;
      if (tempNow < 0) delay += Math.abs(tempNow) * 5; // minutes
      if (precipProb > 70) delay += 15;                 // heavy rain adds 15 mins

      return delay;
    } catch (_) {
      return 0; // fallback – assume no extra delay
    }
  }
}
```

*(In production wrap this in a proper cache / retry strategy.)*

