## 5️⃣ Controllers & Routes

### `src/api/v1/routes.ts`

```ts
import { Router } from 'express';
import { ShipmentController } from '../../controllers/shipment.controller';
import { validateBody } from './validators/shipment.validator';
import { requireAuth } from './middleware/auth.middleware';

const router = Router();

router.post('/shipments', requireAuth, validateBody('create'), ShipmentController.create);
router.put('/shipments/:id', requireAuth, validateBody('update'), ShipmentController.update);
router.patch('/shipments/:id/assign', requireAuth, ShipmentController.assign);
router.get('/shipments/:id/eta', requireAuth, ShipmentController.estimatedEta);

// … more CRUD endpoints …

export default router;
```

### `src/controllers/shipment.controller.ts`

```ts
import { Request, Response, NextFunction } from 'express';
import { ShipmentService } from '../domain/services/ShipmentService';
import { logError } from '../infra/logger';

const svc = new ShipmentService();

/** POST /v1/shipments */
export const create = async (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  try {
    const result = await svc.create(req.body);
    res.status(201).json(result);
  } catch (err) {
    logError(err);
    next(err);
  }
};

/** PATCH /v1/shipments/:id/assign */
export const assign = async (
  req: Request<{ id: string }>,
  res: Response,
  next: NextFunction
) => {
  try {
    const { truckId, driverId } = req.body;
    await svc.assignRoute(Number(req.params.id), Number(truckId), Number(driverId));
    res.sendStatus(204);
  } catch (err) {
    logError(err);
    next(err);
  }
};

export const estimatedEta = async (
  req: Request<{ id: string }>,
  res: Response,
  next: NextFunction
) => {
  try {
    const eta = await svc.getEstimatedArrival(Number(req.params.id));
    res.json({ eta });
  } catch (err) {
    logError(err);
    next(err);
  }
};
```

