## 6️⃣ Validation Middleware

Using Joi (or Yup) – keep it simple here.

```ts
import { celebrate, Segments, Joi } from 'celebrate';

export const validateBody = (schemaKey: keyof typeof schemas) => {
  const schemaMap = {
    create: Joi.object({
      reference: Joi.string().required(),
      weightKg: Joi.number().positive().required()
      // … other fields …
    }),
    update: Joi.object({
      status: Joi.valid(...Object.values(ShipmentStatus)),
      // optional partial updates
    })
  };

  return celebrate({
    [Segments.BODY]: schemaMap[schemaKey]
  });
};
```

